import{_ as t,o as a,c as s,ag as i}from"./chunks/framework.BPmc_f4o.js";const u=JSON.parse(`{"title":"tecs.events","description":"The engine's typed platform event stream: one wide record per event, one ECS event type per kind, and how to observe, copy and inject them","frontmatter":{"description":"The engine's typed platform event stream: one wide record per event, one ECS event type per kind, and how to observe, copy and inject them","outline":"deep"},"headers":[],"relativePath":"modules/events.md","filePath":"modules/events.md"}`),d={name:"modules/events.md"};function n(o,e,r,h,c,l){return a(),s("div",null,[...e[0]||(e[0]=[i(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /modules/events.md for this page in Markdown format</div><h1 id="tecs-events" tabindex="-1">tecs.events <a class="header-anchor" href="#tecs-events" aria-label="Permalink to &quot;tecs.events&quot;">​</a></h1><p><code>tecs.events</code> is the engine&#39;s platform event stream: keys, pointers, fingers, pens, gamepads, windows, displays, drops, the clipboard, audio devices and the application lifecycle, all as one typed vocabulary. Game code never sees an <code>SDL_Event</code>, both because the union is a poor thing to program against and because its pointer is only valid inside the callback that produced it.</p><p>Every platform delivers the same vocabulary: desktop, mobile, replay and tests. Unrecognised SDL events arrive as <code>unknown</code> carrying their numeric type rather than being dropped, so upgrading SDL surfaces new input instead of silently losing it.</p><div class="info custom-block"><p class="custom-block-title">This is not the ECS message bus</p><p><a href="/ecs/events.html"><code>world:emit</code></a> and <code>world:observe</code> are the ECS&#39;s own message bus, which carries whatever event types a game declares. This module is the platform layer that produces one particular family of them. The two meet at exactly one point: each platform kind is registered as an ECS event type, so a platform event is delivered through the same bus a game&#39;s own events are. Everything else about the bus, including addresses, ordering and how a listener is registered, is the ECS&#39;s; see <a href="/ecs/events.html">Events</a>.</p></div><h2 id="observing-a-kind" tabindex="-1">Observing a kind <a class="header-anchor" href="#observing-a-kind" aria-label="Permalink to &quot;Observing a kind&quot;">​</a></h2><p>Events reach a game through the world&#39;s message bus, one ECS event type per kind, at address zero.</p><div class="language-teal vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">teal</span><pre class="shiki shiki-themes github-light-high-contrast tokyo-night vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">world:</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">observe</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">(</span><span style="--shiki-light:#023B95;--shiki-dark:#FF9E64;">0</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">, tecs.</span><span style="--shiki-light:#0E1116;--shiki-dark:#C0CAF5;">events</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">.</span><span style="--shiki-light:#0E1116;--shiki-dark:#C0CAF5;">on</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">.</span><span style="--shiki-light:#0E1116;--shiki-dark:#C0CAF5;">dropFile</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">, </span><span style="--shiki-light:#A0111F;--shiki-dark:#BB9AF7;">function</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">(event: </span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">tecs</span><span style="--shiki-light:#0E1116;--shiki-dark:#89DDFF;">.</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">events</span><span style="--shiki-light:#0E1116;--shiki-dark:#89DDFF;">.</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">Event</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">)</span></span>
<span class="line"><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">    load</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">(event.</span><span style="--shiki-light:#0E1116;--shiki-dark:#C0CAF5;">text</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">)</span></span>
<span class="line"><span style="--shiki-light:#A0111F;--shiki-dark:#BB9AF7;">end</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">)</span></span></code></pre></div><p>That handler is called for dropped files and for nothing else. A type per kind is what buys that over one type carrying the kind, where every subscriber is handed every kind and filters it back out again.</p><p><code>events.on</code> is a record with a field per kind, so a misspelled kind is a compile error on the key rather than an observer that is never called.</p><p>Nothing is emitted for a kind nobody observes, so a stream of motion at device rate costs a table lookup and a gate rather than a dispatch.</p><h3 id="where-an-observer-runs" tabindex="-1">Where an observer runs <a class="header-anchor" href="#where-an-observer-runs" aria-label="Permalink to &quot;Where an observer runs&quot;">​</a></h3><p>An observer is not a system, and the difference matters for anything it touches. The drain runs before <code>world:update</code>, so an observer fires ahead of every system in the frame the event belongs to and outside every phase: no fixed step, no pause and no state gating apply to it, and its mutations land at once rather than at a phase boundary.</p><p>A reaction that wants to be in phase does what <a href="/modules/input.html"><code>Input</code></a> does, which is fold the event into something a system reads. <code>Input</code> is folded before any observer runs and is unaffected by all of this.</p><h3 id="typeof" tabindex="-1">typeOf <a class="header-anchor" href="#typeof" aria-label="Permalink to &quot;typeOf&quot;">​</a></h3><p>The event type for a kind held as a string.</p><div class="language-teal vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">teal</span><pre class="shiki shiki-themes github-light-high-contrast tokyo-night vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0111F;--shiki-dark:#BB9AF7;">function</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;"> events</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">.</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">typeOf</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">(kind: </span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">string</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">): </span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">Event</span></span></code></pre></div><p><strong>Parameters:</strong></p><ul><li><code>kind</code>: one of the names in the <a href="#kind-reference">kind reference</a>.</li></ul><p><strong>Returns:</strong> the ECS event type to observe, or nil for a name this build does not know. This is what <code>events.on</code> is for code that cannot spell the kind in source, which is the conversion itself and the debug tools.</p><h3 id="kinds" tabindex="-1">kinds <a class="header-anchor" href="#kinds" aria-label="Permalink to &quot;kinds&quot;">​</a></h3><p>Every kind this build recognises, sorted.</p><div class="language-teal vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">teal</span><pre class="shiki shiki-themes github-light-high-contrast tokyo-night vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0111F;--shiki-dark:#BB9AF7;">function</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;"> events</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">.</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">kinds</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">(): </span><span style="--shiki-light:#023B95;--shiki-dark:#A9B1D6;">{</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">string</span><span style="--shiki-light:#023B95;--shiki-dark:#A9B1D6;">}</span></span></code></pre></div><p>For tooling that enumerates them. A kind whose SDL constant this build does not have is not in the list, and <code>unknown</code> is not either, since nothing maps to it.</p><h2 id="the-borrow-rule" tabindex="-1">The borrow rule <a class="header-anchor" href="#the-borrow-rule" aria-label="Permalink to &quot;The borrow rule&quot;">​</a></h2><p><code>Event</code> is one wide record discriminated by <code>kind</code> rather than a union of per-kind records. Teal can express the union, but not a union that pools, and an event stream that allocates per event is not one this engine can use.</p><p>One record is reused for the whole process, so the record an observer receives is the record the next event overwrites. Read it inside the handler, or copy it, but do not keep it.</p><p>The kind determines which fields are meaningful and the rest are stale. Fields that answer a question by existing, a string, a list or a flag, are cleared on every event, so <code>event.text ~= nil</code> and <code>event.eraser</code> cannot read as the previous event&#39;s payload; a stale number is only read by code that ignored the kind.</p><h3 id="copy" tabindex="-1">copy <a class="header-anchor" href="#copy" aria-label="Permalink to &quot;copy&quot;">​</a></h3><p>Returns an independent copy.</p><div class="language-teal vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">teal</span><pre class="shiki shiki-themes github-light-high-contrast tokyo-night vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0111F;--shiki-dark:#BB9AF7;">function</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;"> events</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">.</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">copy</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">(event: </span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">Event</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">): </span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">Event</span></span></code></pre></div><p>Shallow, which is enough because every field is a number, a string or a boolean except the three lists, and those are freshly built per event rather than reused. It allocates, so it is for the events a recorder or a tool keeps and not for the stream.</p><h2 id="event-fields" tabindex="-1">Event fields <a class="header-anchor" href="#event-fields" aria-label="Permalink to &quot;Event fields&quot;">​</a></h2><p>Every event carries <code>kind</code>, <code>timestamp</code> and <code>sdlType</code>. The rest are filled per kind.</p><h3 id="identity-and-time" tabindex="-1">Identity and time <a class="header-anchor" href="#identity-and-time" aria-label="Permalink to &quot;Identity and time&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>kind</code></td><td><code>string</code></td><td>What happened. Determines which other fields mean anything.</td></tr><tr><td><code>timestamp</code></td><td><code>number</code></td><td>Nanoseconds since SDL started, as SDL reported it. That epoch is not the clock <a href="/modules/time.html#now"><code>time.now</code></a> reads, so it orders events against each other and against nothing else.</td></tr><tr><td><code>arrival</code></td><td><code>number</code></td><td>Monotonic seconds on the clock <code>clock.now</code> reads, converted by the host from the stamp SDL put on the event when it produced it. Nil for an event that did not come through the host&#39;s queue, such as a replayed one.</td></tr><tr><td><code>sdlType</code></td><td><code>integer</code></td><td>Numeric SDL type, set on every event and the only useful field on <code>unknown</code>.</td></tr><tr><td><code>which</code></td><td><code>number</code></td><td>The device the event came from: a gamepad, keyboard, mouse, pen, sensor, display or window. These identifiers are 32 bits and fit a Lua number exactly.</td></tr></tbody></table><p><code>arrival</code> is not where the host was handed the event, which is a different and much kinder number: SDL only hands events over while the main thread is pumping, and most of what a player waits through is time the thread was doing something else. Dating an event from delivery would leave the measurement least trustworthy in exactly the frames worth catching.</p><h3 id="keyboard-and-text" tabindex="-1">Keyboard and text <a class="header-anchor" href="#keyboard-and-text" aria-label="Permalink to &quot;Keyboard and text&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>scancode</code></td><td><code>integer</code></td><td>Physical key position, which is what a movement binding wants: WASD stays in the same place on every layout.</td></tr><tr><td><code>keycode</code></td><td><code>integer</code></td><td>The key the layout produces, which is what a text binding and a prompt want. Both are carried, because neither answers the other&#39;s question.</td></tr><tr><td><code>modifiers</code></td><td><code>integer</code></td><td>Modifier keys held when the key event was produced, as a mask.</td></tr><tr><td><code>repeated</code></td><td><code>boolean</code></td><td>True when the platform is repeating a held key rather than reporting a new press.</td></tr><tr><td><code>down</code></td><td><code>boolean</code></td><td>Whether the button or key this event describes went down.</td></tr><tr><td><code>text</code></td><td><code>string</code></td><td>Text committed by an input method, being composed by one, or dropped onto the window.</td></tr><tr><td><code>start</code></td><td><code>integer</code></td><td>Cursor position within composing text.</td></tr><tr><td><code>length</code></td><td><code>integer</code></td><td>Selection length within composing text.</td></tr><tr><td><code>candidates</code></td><td><code>{string}</code></td><td>Candidates an input method is offering. Nil when the platform offers none.</td></tr><tr><td><code>selected</code></td><td><code>integer</code></td><td>Which candidate is selected.</td></tr><tr><td><code>horizontal</code></td><td><code>boolean</code></td><td>Whether the platform lays its candidates out horizontally.</td></tr></tbody></table><h3 id="pointers-wheels-and-gestures" tabindex="-1">Pointers, wheels and gestures <a class="header-anchor" href="#pointers-wheels-and-gestures" aria-label="Permalink to &quot;Pointers, wheels and gestures&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>x</code>, <code>y</code></td><td><code>number</code></td><td>Pointer position, in window coordinates.</td></tr><tr><td><code>dx</code>, <code>dy</code></td><td><code>number</code></td><td>Movement since the previous event of this kind.</td></tr><tr><td><code>normalX</code>, <code>normalY</code></td><td><code>number</code></td><td>Position as the platform reported it, in 0..1 across the window. Touch is normalised at source, and a normalised position survives a resize where a window coordinate does not.</td></tr><tr><td><code>button</code></td><td><code>integer</code></td><td>Mouse, gamepad or pen button.</td></tr><tr><td><code>clicks</code></td><td><code>integer</code></td><td>How many times this button was pressed in quick succession, as the platform counts it against its own double-click interval. One for a single click, two for a double.</td></tr><tr><td><code>wheelX</code>, <code>wheelY</code></td><td><code>number</code></td><td>Wheel movement. Positive <code>wheelY</code> is a scroll away from the player and positive <code>wheelX</code> is a scroll to the right.</td></tr><tr><td><code>wheelTicksX</code>, <code>wheelTicksY</code></td><td><code>integer</code></td><td>The same movement accumulated to whole notches by the platform, on the same sign convention. What a menu stepping one item per notch reads.</td></tr><tr><td><code>flipped</code></td><td><code>boolean</code></td><td>Whether a wheel event handed to <code>push</code> is one a platform with natural scrolling would send. Read only there; see below.</td></tr><tr><td><code>scale</code></td><td><code>number</code></td><td>Zoom factor a pinch reports since the previous event in it. Below one is a pinch closed, above one is a pinch opened.</td></tr><tr><td><code>synthetic</code></td><td><code>boolean</code></td><td>True when the platform produced this mouse event from a touch or a pen rather than from a mouse. A game that also handles touch would otherwise act on the same gesture twice.</td></tr></tbody></table><p>Natural scrolling is undone by the conversion rather than left for each reader to discover: SDL reports a flipped wheel by negating both axes and setting a flag, so <code>wheelX</code> and <code>wheelY</code> mean one thing everywhere and nothing above binds a sign twice.</p><p>Touch positions are converted into window coordinates using the size <a href="#settouchscale"><code>setTouchScale</code></a> was last told about, so touch and mouse arrive in the same units.</p><h3 id="touch-pens-and-gamepad-touchpads" tabindex="-1">Touch, pens and gamepad touchpads <a class="header-anchor" href="#touch-pens-and-gamepad-touchpads" aria-label="Permalink to &quot;Touch, pens and gamepad touchpads&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>finger</code></td><td><code>string</code></td><td>Touch finger identity. 64 bits, carried as an opaque string rather than a number that might silently round.</td></tr><tr><td><code>touchDevice</code></td><td><code>string</code></td><td>The touch device the finger belongs to, on the same terms.</td></tr><tr><td><code>touchpad</code></td><td><code>integer</code></td><td>Gamepad touchpad index.</td></tr><tr><td><code>fingerIndex</code></td><td><code>integer</code></td><td>The finger&#39;s slot on that touchpad. A touchpad finger is identified by position on the device, not by a 64-bit id.</td></tr><tr><td><code>pressure</code></td><td><code>number</code></td><td>How hard a finger is pressing, in 0..1, on a touch surface or a gamepad touchpad. A pen reports pressure as an axis instead, so a pen event leaves this holding whatever the last touch put there.</td></tr><tr><td><code>eraser</code></td><td><code>boolean</code></td><td>Whether the pen&#39;s eraser end is in use.</td></tr><tr><td><code>penState</code></td><td><code>integer</code></td><td>Everything the pen was doing at the instant of the event, as a mask of the platform&#39;s <code>SDL_PEN_INPUT_*</code> values: tip down, eraser end in use, proximity, and each barrel button. Not carried on the proximity events, which report no state.</td></tr><tr><td><code>axis</code></td><td><code>integer</code></td><td>Gamepad or pen axis.</td></tr><tr><td><code>value</code></td><td><code>number</code></td><td>That axis&#39;s value, in -1..1.</td></tr></tbody></table><h3 id="sensors" tabindex="-1">Sensors <a class="header-anchor" href="#sensors" aria-label="Permalink to &quot;Sensors&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>sensor</code></td><td><code>integer</code></td><td>Sensor identity on a gamepad sensor event.</td></tr><tr><td><code>sensorX</code>, <code>sensorY</code>, <code>sensorZ</code></td><td><code>number</code></td><td>The reading&#39;s first three components.</td></tr><tr><td><code>sensorData</code></td><td><code>{number}</code></td><td>The whole reading. A standalone sensor reports up to six components where a gamepad reports three.</td></tr><tr><td><code>sensorTimestamp</code></td><td><code>number</code></td><td>When the hardware took the reading, in nanoseconds on the sensor&#39;s own clock. Like <code>timestamp</code> it orders readings against each other and against nothing else, which is what integrating a rotation over them needs.</td></tr></tbody></table><h3 id="drops-the-clipboard-audio-devices-and-payloads" tabindex="-1">Drops, the clipboard, audio devices and payloads <a class="header-anchor" href="#drops-the-clipboard-audio-devices-and-payloads" aria-label="Permalink to &quot;Drops, the clipboard, audio devices and payloads&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>text</code></td><td><code>string</code></td><td>The dropped file&#39;s path, or the dropped text.</td></tr><tr><td><code>source</code></td><td><code>string</code></td><td>Where a dropped file or text came from, when the platform says.</td></tr><tr><td><code>mimeTypes</code></td><td><code>{string}</code></td><td>Clipboard formats on offer. The same list <a href="/modules/system.html#clipboardmimetypes"><code>clipboard.mimeTypes</code></a> answers.</td></tr><tr><td><code>owner</code></td><td><code>boolean</code></td><td>Whether the clipboard&#39;s new contents are this application&#39;s own.</td></tr><tr><td><code>recording</code></td><td><code>boolean</code></td><td>Whether an audio device is a recording device.</td></tr><tr><td><code>data1</code>, <code>data2</code></td><td><code>integer</code></td><td>Window, display and user payloads as SDL reports them. A user event&#39;s code arrives in <code>data1</code>; the two data pointers beside it do not cross, since a pointer is not a value this vocabulary can carry.</td></tr></tbody></table><h2 id="kind-reference" tabindex="-1">Kind reference <a class="header-anchor" href="#kind-reference" aria-label="Permalink to &quot;Kind reference&quot;">​</a></h2><h3 id="application-lifecycle" tabindex="-1">Application lifecycle <a class="header-anchor" href="#application-lifecycle" aria-label="Permalink to &quot;Application lifecycle&quot;">​</a></h3><p><code>quit</code>, <code>terminating</code>, <code>lowMemory</code>, <code>appWillEnterBackground</code>, <code>appDidEnterBackground</code>, <code>appWillEnterForeground</code>, <code>appDidEnterForeground</code>, <code>localeChanged</code>, <code>themeChanged</code>.</p><p>SDL dispatches six of these from its event watcher rather than queueing them, and the instant they arrive is the only one a game gets on some platforms. The host therefore answers them where they arrive, by calling a hook on the <a href="/modules/application.html">application</a>, and queues the event as well, so a game can observe the change like any other. The hook is where a game meets the platform&#39;s deadline; the stream is where it observes the change. These six carry no stamp from SDL, so <code>arrival</code> on them is where they were delivered, and <a href="#isinput"><code>isInput</code></a> excludes them.</p><h3 id="displays" tabindex="-1">Displays <a class="header-anchor" href="#displays" aria-label="Permalink to &quot;Displays&quot;">​</a></h3><p><code>displayOrientation</code>, <code>displayAdded</code>, <code>displayRemoved</code>, <code>displayMoved</code>, <code>displayScaleChanged</code>, <code>displayDesktopModeChanged</code>, <code>displayCurrentModeChanged</code>, <code>displayUsableBoundsChanged</code>.</p><p><code>which</code> is the display the event is about, which is its whole subject: a display event that did not carry one would name a change on a machine with two monitors without saying which of them changed. <a href="/modules/window.html#displays"><code>Window</code></a> is where the new state is read from.</p><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><p><code>windowShown</code>, <code>windowHidden</code>, <code>windowExposed</code>, <code>windowMoved</code>, <code>windowResized</code>, <code>windowPixelSizeChanged</code>, <code>windowMinimized</code>, <code>windowMaximized</code>, <code>windowRestored</code>, <code>windowMouseEnter</code>, <code>windowMouseLeave</code>, <code>windowFocusGained</code>, <code>windowFocusLost</code>, <code>windowCloseRequested</code>, <code>windowDisplayChanged</code>, <code>windowDisplayScaleChanged</code>, <code>windowSafeAreaChanged</code>, <code>windowOccluded</code>, <code>windowEnterFullscreen</code>, <code>windowLeaveFullscreen</code>.</p><p><code>which</code> is the window id, which is what <a href="/modules/window.html#id"><code>Window:id</code></a> answers. An event reports a change and nothing reports the state a window started in, so <a href="/modules/window.html"><code>Window</code></a> has a getter for every one of these facts.</p><h3 id="keyboard-and-text-1" tabindex="-1">Keyboard and text <a class="header-anchor" href="#keyboard-and-text-1" aria-label="Permalink to &quot;Keyboard and text&quot;">​</a></h3><p><code>keyDown</code>, <code>keyUp</code>, <code>textEditing</code>, <code>textCandidates</code>, <code>textInput</code>, <code>keymapChanged</code>, <code>keyboardAdded</code>, <code>keyboardRemoved</code>, <code>screenKeyboardShown</code>, <code>screenKeyboardHidden</code>.</p><h3 id="mouse" tabindex="-1">Mouse <a class="header-anchor" href="#mouse" aria-label="Permalink to &quot;Mouse&quot;">​</a></h3><p><code>mouseMotion</code>, <code>mouseDown</code>, <code>mouseUp</code>, <code>mouseWheel</code>, <code>mouseAdded</code>, <code>mouseRemoved</code>.</p><h3 id="touch-and-gestures" tabindex="-1">Touch and gestures <a class="header-anchor" href="#touch-and-gestures" aria-label="Permalink to &quot;Touch and gestures&quot;">​</a></h3><p><code>fingerDown</code>, <code>fingerUp</code>, <code>fingerMotion</code>, <code>fingerCanceled</code>, <code>pinchBegin</code>, <code>pinchUpdate</code>, <code>pinchEnd</code>.</p><h3 id="pen" tabindex="-1">Pen <a class="header-anchor" href="#pen" aria-label="Permalink to &quot;Pen&quot;">​</a></h3><p><code>penProximityIn</code>, <code>penProximityOut</code>, <code>penDown</code>, <code>penUp</code>, <code>penMotion</code>, <code>penButtonDown</code>, <code>penButtonUp</code>, <code>penAxis</code>.</p><h3 id="gamepad" tabindex="-1">Gamepad <a class="header-anchor" href="#gamepad" aria-label="Permalink to &quot;Gamepad&quot;">​</a></h3><p><code>gamepadAdded</code>, <code>gamepadRemoved</code>, <code>gamepadRemapped</code>, <code>gamepadButtonDown</code>, <code>gamepadButtonUp</code>, <code>gamepadAxis</code>, <code>gamepadSensor</code>, <code>gamepadTouchpadDown</code>, <code>gamepadTouchpadUp</code>, <code>gamepadTouchpadMotion</code>.</p><p>Gamepad axis values arrive as signed 16-bit and are reported as -1..1.</p><h3 id="drag-and-drop" tabindex="-1">Drag and drop <a class="header-anchor" href="#drag-and-drop" aria-label="Permalink to &quot;Drag and drop&quot;">​</a></h3><p><code>dropFile</code>, <code>dropText</code>, <code>dropBegin</code>, <code>dropComplete</code>, <code>dropPosition</code>.</p><h3 id="everything-else" tabindex="-1">Everything else <a class="header-anchor" href="#everything-else" aria-label="Permalink to &quot;Everything else&quot;">​</a></h3><p><code>clipboardUpdate</code>, <code>audioDeviceAdded</code>, <code>audioDeviceRemoved</code>, <code>audioDeviceFormatChanged</code>, <code>sensorUpdate</code>, <code>user</code>, and <code>unknown</code> for an SDL event this build has no name for, which carries <code>sdlType</code> and nothing else worth reading.</p><h2 id="isinput" tabindex="-1">isInput <a class="header-anchor" href="#isinput" aria-label="Permalink to &quot;isInput&quot;">​</a></h2><p>Whether a kind carries player input rather than describing the platform.</p><div class="language-teal vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">teal</span><pre class="shiki shiki-themes github-light-high-contrast tokyo-night vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0111F;--shiki-dark:#BB9AF7;">function</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;"> events</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">.</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">isInput</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">(kind: </span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">string</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">): </span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">boolean</span></span></code></pre></div><p>True for the key, text, mouse, finger, pinch, pen and gamepad kinds a player produces, and false for everything the platform reports about itself. Latency is only meaningful for these: nobody is waiting on a window expose.</p><h2 id="injecting-an-event" tabindex="-1">Injecting an event <a class="header-anchor" href="#injecting-an-event" aria-label="Permalink to &quot;Injecting an event&quot;">​</a></h2><h3 id="push" tabindex="-1">push <a class="header-anchor" href="#push" aria-label="Permalink to &quot;push&quot;">​</a></h3><p>Pushes a synthetic event onto SDL&#39;s own queue.</p><div class="language-teal vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">teal</span><pre class="shiki shiki-themes github-light-high-contrast tokyo-night vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0111F;--shiki-dark:#BB9AF7;">function</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;"> events</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">.</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">push</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">(kind: </span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">string</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">, fields: </span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">Event</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">)</span></span></code></pre></div><p><strong>Parameters:</strong></p><ul><li><code>kind</code>: one of <a href="#kinds"><code>events.kinds()</code></a>. An unrecognised name raises.</li><li><code>fields</code>: a partial <code>Event</code>. Only the fields a kind uses are read.</li></ul><p>Takes the engine&#39;s vocabulary rather than an SDL union, so a test or a tool can inject input without knowing SDL&#39;s layout. Payloads are filled for the key, mouse, wheel, pen, gamepad, device, pinch, window and display kinds; any other recognised kind is pushed carrying its type and nothing else, which is what a kind whose payload nobody injects needs and is not what a caller expecting a full event would assume.</p><p>SDL stamps the timestamp, so a pushed event arrives ordered against real ones rather than ahead of them.</p><p><strong>Example:</strong></p><div class="language-teal vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">teal</span><pre class="shiki shiki-themes github-light-high-contrast tokyo-night vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">tecs.</span><span style="--shiki-light:#0E1116;--shiki-dark:#C0CAF5;">events</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">.</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">push</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">(</span><span style="--shiki-light:#032563;--shiki-dark:#89DDFF;">&quot;</span><span style="--shiki-light:#032563;--shiki-dark:#9ECE6A;">mouseDown</span><span style="--shiki-light:#032563;--shiki-dark:#89DDFF;">&quot;</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">, { </span><span style="--shiki-light:#0E1116;--shiki-dark:#C0CAF5;">button </span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">= </span><span style="--shiki-light:#023B95;--shiki-dark:#FF9E64;">1</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">, </span><span style="--shiki-light:#0E1116;--shiki-dark:#C0CAF5;">x </span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">= </span><span style="--shiki-light:#023B95;--shiki-dark:#FF9E64;">120</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">, </span><span style="--shiki-light:#0E1116;--shiki-dark:#C0CAF5;">y </span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">= </span><span style="--shiki-light:#023B95;--shiki-dark:#FF9E64;">64</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;"> })</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">tecs.</span><span style="--shiki-light:#0E1116;--shiki-dark:#C0CAF5;">events</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">.</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">push</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">(</span><span style="--shiki-light:#032563;--shiki-dark:#89DDFF;">&quot;</span><span style="--shiki-light:#032563;--shiki-dark:#9ECE6A;">gamepadAxis</span><span style="--shiki-light:#032563;--shiki-dark:#89DDFF;">&quot;</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">, { </span><span style="--shiki-light:#0E1116;--shiki-dark:#C0CAF5;">which </span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">= </span><span style="--shiki-light:#023B95;--shiki-dark:#FF9E64;">0</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">, </span><span style="--shiki-light:#0E1116;--shiki-dark:#C0CAF5;">axis </span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">= </span><span style="--shiki-light:#023B95;--shiki-dark:#FF9E64;">0</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">, </span><span style="--shiki-light:#0E1116;--shiki-dark:#C0CAF5;">value </span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">= </span><span style="--shiki-light:#A0111F;--shiki-dark:#89DDFF;">-</span><span style="--shiki-light:#023B95;--shiki-dark:#FF9E64;">1.0</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;"> })</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">A flipped wheel round-trips as a normalisation</p><p>A wheel payload is written the way the platform writes one, so <code>flipped</code> sets the direction and the axes beside it are left as given. The conversion then negates them, which is what a caller asking for a flipped scroll is asking to see: the round trip is the normalisation, not the identity.</p></div><h2 id="wiring-the-stream" tabindex="-1">Wiring the stream <a class="header-anchor" href="#wiring-the-stream" aria-label="Permalink to &quot;Wiring the stream&quot;">​</a></h2><p>These three are how the loop and a replay driver reach the module. <a href="/modules/application.html"><code>Application</code></a> calls the first two for you.</p><h3 id="settouchscale" tabindex="-1">setTouchScale <a class="header-anchor" href="#settouchscale" aria-label="Permalink to &quot;setTouchScale&quot;">​</a></h3><p>Tells the converter how large the window is.</p><div class="language-teal vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">teal</span><pre class="shiki shiki-themes github-light-high-contrast tokyo-night vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0111F;--shiki-dark:#BB9AF7;">function</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;"> events</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">.</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">setTouchScale</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">(width: </span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">number</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">, height: </span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">number</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">)</span></span></code></pre></div><p>Touch arrives normalised, so this is what lets touch positions be reported in the same units mouse positions arrive in as well as in the platform&#39;s own 0..1. Logical window size, not pixels: scaling touch by the pixel size would put the two pointers in different units on every high-density display.</p><h3 id="drain" tabindex="-1">drain <a class="header-anchor" href="#drain" aria-label="Permalink to &quot;drain&quot;">​</a></h3><p>Converts and dispatches a queue of SDL events, in arrival order.</p><div class="language-teal vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">teal</span><pre class="shiki shiki-themes github-light-high-contrast tokyo-night vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0111F;--shiki-dark:#BB9AF7;">function</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;"> events</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">.</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">drain</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">(queue: </span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">loader</span><span style="--shiki-light:#0E1116;--shiki-dark:#89DDFF;">.</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">CValue</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">, count: </span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">integer</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">,</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">                      handler: </span><span style="--shiki-light:#A0111F;--shiki-dark:#BB9AF7;">function</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">(</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">Event</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">), arrivals?: </span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">loader</span><span style="--shiki-light:#0E1116;--shiki-dark:#89DDFF;">.</span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">CValue</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">)</span></span></code></pre></div><p>The host owns the queue and clears it; this only reads. <code>arrivals</code> is the host&#39;s parallel array of performance counter readings, one per event, converted there from the stamp SDL put on each event as it was produced. Given it, every converted event carries <code>arrival</code> in the units <code>clock.now</code> reports.</p><p>When a replay <code>source</code> is installed, it is called instead and the queue is not read at all.</p><h3 id="replaying-a-stream" tabindex="-1">Replaying a stream <a class="header-anchor" href="#replaying-a-stream" aria-label="Permalink to &quot;Replaying a stream&quot;">​</a></h3><p><code>events.source</code> is <code>function(handler: function(Event))</code>. Installed by a replay driver, it is called instead of draining the host queue and is expected to invoke the handler for each recorded event. It is also the seam a platform that is not SDL supplies, producing the engine&#39;s typed values directly rather than translating an <code>SDL_Event</code>.</p><p>Pair it with <a href="/modules/time.html#driving-a-replay"><code>time.provider</code></a>, which replaces the frame delta on the same terms.</p><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Reference&quot;">​</a></h2><p>Every function and type this module carries, rendered from <code>src/tecs/platform/events.tl</code>.</p><p><a id="tecs.events.Event"></a></p><h3 id="tecs-events-event" tabindex="-1">tecs.events.Event <a class="header-anchor" href="#tecs-events-event" aria-label="Permalink to &quot;tecs.events.Event&quot;">​</a></h3><pre><code><a href="#tecs.events.Event">tecs.events.Event</a>: Event
</code></pre><p>One event, discriminated by <code>kind</code>. The record handed to a handler is reused, so anything retaining one takes a copy through <code>events.copy</code>. <a id="tecs.events.copy"></a></p><h3 id="tecs-events-copy" tabindex="-1">tecs.events.copy <a class="header-anchor" href="#tecs-events-copy" aria-label="Permalink to &quot;tecs.events.copy&quot;">​</a></h3><pre><code>function <a href="#tecs.events.copy">tecs.events.copy</a>(event: <a href="#tecs.events.Event">Event</a>): <a href="#tecs.events.Event">Event</a>
</code></pre><p>Returns an independent copy, for code that must retain an event past the handler that received it.</p><p>Shallow, which is enough because every field is a number, a string or a boolean except the three lists, and those are freshly built per event rather than reused. Allocates, so this is for the events a recorder or a tool keeps and not for the stream.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Type</th><th>Name</th><th>Description</th></tr></thead><tbody><tr><td><code><a href="#tecs.events.Event">Event</a></code></td><td><code>event</code></td><td></td></tr></tbody></table><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code><a href="#tecs.events.Event">Event</a></code></td><td></td></tr></tbody></table><p><a id="tecs.events.drain"></a></p><h3 id="tecs-events-drain" tabindex="-1">tecs.events.drain <a class="header-anchor" href="#tecs-events-drain" aria-label="Permalink to &quot;tecs.events.drain&quot;">​</a></h3><pre><code>function <a href="#tecs.events.drain">tecs.events.drain</a>(queue: loader.CValue, count: integer, handler: function(<a href="#tecs.events.Event">Event</a>), arrivals: loader.CValue)
</code></pre><p>Converts and dispatches a queue of SDL events, in arrival order.</p><p>The host owns the queue and clears it; this only reads. A replay driver installs <code>source</code> instead, which is handed the same handler and calls it with recorded events.</p><p><code>arrivals</code> is the host&#39;s parallel array of performance counter readings, one per event, converted there from the stamp SDL put on each event as it was produced. Given it, every converted event carries <code>arrival</code> in the units <code>time.now</code> reports.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Type</th><th>Name</th><th>Description</th></tr></thead><tbody><tr><td><code>loader.CValue</code></td><td><code>queue</code></td><td></td></tr><tr><td><code>integer</code></td><td><code>count</code></td><td></td></tr><tr><td><code>function(<a href="#tecs.events.Event">Event</a>)</code></td><td><code>handler</code></td><td></td></tr><tr><td><code>loader.CValue</code></td><td><code>arrivals</code></td><td></td></tr></tbody></table><p><a id="tecs.events.isInput"></a></p><h3 id="tecs-events-isinput" tabindex="-1">tecs.events.isInput <a class="header-anchor" href="#tecs-events-isinput" aria-label="Permalink to &quot;tecs.events.isInput&quot;">​</a></h3><pre><code>function <a href="#tecs.events.isInput">tecs.events.isInput</a>(kind: string): boolean
</code></pre><p>Whether a kind carries player input rather than describing the platform.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Type</th><th>Name</th><th>Description</th></tr></thead><tbody><tr><td><code>string</code></td><td><code>kind</code></td><td></td></tr></tbody></table><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>boolean</code></td><td></td></tr></tbody></table><p><a id="tecs.events.kinds"></a></p><h3 id="tecs-events-kinds" tabindex="-1">tecs.events.kinds <a class="header-anchor" href="#tecs-events-kinds" aria-label="Permalink to &quot;tecs.events.kinds&quot;">​</a></h3><pre><code>function <a href="#tecs.events.kinds">tecs.events.kinds</a>(): {string}
</code></pre><p>Every kind this build recognises, for tooling that enumerates them.</p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>{string}</code></td><td></td></tr></tbody></table><p><a id="tecs.events.on"></a></p><h3 id="tecs-events-on" tabindex="-1">tecs.events.on <a class="header-anchor" href="#tecs-events-on" aria-label="Permalink to &quot;tecs.events.on&quot;">​</a></h3><pre><code><a href="#tecs.events.on">tecs.events.on</a>: KindTypes
</code></pre><p>One ECS event type per kind, to observe at address zero. See <code>KindTypes</code>. <a id="tecs.events.push"></a></p><h3 id="tecs-events-push" tabindex="-1">tecs.events.push <a class="header-anchor" href="#tecs-events-push" aria-label="Permalink to &quot;tecs.events.push&quot;">​</a></h3><pre><code>function <a href="#tecs.events.push">tecs.events.push</a>(kind: string, fields: <a href="#tecs.events.Event">Event</a>)
</code></pre><p>Pushes a synthetic event onto SDL&#39;s own queue.</p><p>Takes the engine&#39;s vocabulary rather than an SDL union, so a test or a tool can inject input without knowing SDL&#39;s layout. Only the fields a kind uses are read.</p><p>Payloads are filled for the key, mouse, wheel, pen, gamepad, device, pinch, window and display kinds. Any other recognised kind is pushed carrying its type and nothing else, which is what a kind whose payload nobody injects needs and is not what a caller expecting a full event would assume.</p><p>A wheel payload is written the way the platform writes one, so <code>flipped</code> sets the direction and the axes beside it are left as given. The conversion then negates them, which is what a caller asking for a flipped scroll is asking to see: the round trip is the normalisation, not the identity.</p><p>SDL stamps the timestamp, so a pushed event arrives ordered against real ones rather than ahead of them.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Type</th><th>Name</th><th>Description</th></tr></thead><tbody><tr><td><code>string</code></td><td><code>kind</code></td><td>One of <code>events.kinds()</code>. An unrecognised name raises.</td></tr><tr><td><code><a href="#tecs.events.Event">Event</a></code></td><td><code>fields</code></td><td></td></tr></tbody></table><p><a id="tecs.events.setTouchScale"></a></p><h3 id="tecs-events-settouchscale" tabindex="-1">tecs.events.setTouchScale <a class="header-anchor" href="#tecs-events-settouchscale" aria-label="Permalink to &quot;tecs.events.setTouchScale&quot;">​</a></h3><pre><code>function <a href="#tecs.events.setTouchScale">tecs.events.setTouchScale</a>(width: number, height: number)
</code></pre><p>Tells the converter how large the window is, so touch positions arrive in the same units as mouse positions as well as in the platform&#39;s own 0..1.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Type</th><th>Name</th><th>Description</th></tr></thead><tbody><tr><td><code>number</code></td><td><code>width</code></td><td></td></tr><tr><td><code>number</code></td><td><code>height</code></td><td></td></tr></tbody></table><p><a id="tecs.events.source"></a></p><h3 id="tecs-events-source" tabindex="-1">tecs.events.source <a class="header-anchor" href="#tecs-events-source" aria-label="Permalink to &quot;tecs.events.source&quot;">​</a></h3><pre><code>function <a href="#tecs.events.source">tecs.events.source</a>(function(<a href="#tecs.events.Event">Event</a>))
</code></pre><p>Installed by a replay driver. Called instead of draining the host queue, and expected to invoke the handler for each recorded event.</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Type</th><th>Name</th><th>Description</th></tr></thead><tbody><tr><td><code>function(<a href="#tecs.events.Event">Event</a>)</code></td><td></td><td></td></tr></tbody></table><p><a id="tecs.events.typeOf"></a></p><h3 id="tecs-events-typeof" tabindex="-1">tecs.events.typeOf <a class="header-anchor" href="#tecs-events-typeof" aria-label="Permalink to &quot;tecs.events.typeOf&quot;">​</a></h3><pre><code>function <a href="#tecs.events.typeOf">tecs.events.typeOf</a>(kind: string): <a href="#tecs.events.Event">Event</a>
</code></pre><p>The event type for a kind, or nil for a name this build does not know.</p><p>What <code>on</code> is for code holding a kind it cannot spell in source, which is the conversion itself and the debug tools.</p><h4 id="parameters-6" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-6" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Type</th><th>Name</th><th>Description</th></tr></thead><tbody><tr><td><code>string</code></td><td><code>kind</code></td><td>A kind name as <code>on</code> spells it. Names are this build&#39;s, so a kind SDL added later is unknown here rather than an error.</td></tr></tbody></table><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code><a href="#tecs.events.Event">Event</a></code></td><td>The event type to observe, or nil for a name this build does not carry.</td></tr></tbody></table>`,173)])])}const k=t(d,[["render",n]]);export{u as __pageData,k as default};
